import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.DFwwXrrM.js";const u=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":null}'),o={name:"guide/getting-started.md"};function r(d,e,c,n,s,h){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>Still 是一个 Windows 桌面音乐播放器。第一次使用时，可以先安装应用、导入本地音乐文件夹，再根据需要调整歌词和主题。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><p>前往 <a href="https://github.com/lrm-com/Still/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 下载最新 Windows 安装包。</p><p>当前版本：<code>1.0.0-beta.2</code></p><h2 id="导入音乐" tabindex="-1">导入音乐 <a class="header-anchor" href="#导入音乐" aria-label="Permalink to &quot;导入音乐&quot;">​</a></h2><ol><li>打开 Still。</li><li>进入音乐库或歌曲列表。</li><li>选择本地音乐文件夹。</li><li>Still 会递归扫描文件夹中的音频文件，并读取元数据、封面和歌词。</li></ol><p>支持的音频格式：</p><ul><li><code>.mp3</code></li><li><code>.flac</code></li><li><code>.wav</code></li><li><code>.ogg</code></li><li><code>.m4a</code></li><li><code>.aac</code></li></ul><h2 id="浏览音乐" tabindex="-1">浏览音乐 <a class="header-anchor" href="#浏览音乐" aria-label="Permalink to &quot;浏览音乐&quot;">​</a></h2><p>导入后可以按以下方式查看音乐：</p><ul><li>歌曲</li><li>艺术家</li><li>专辑</li><li>文件夹</li><li>歌单</li></ul><p>歌曲列表支持搜索和排序。可按标题、艺术家、专辑、年份、时长、文件名、修改时间和文件大小整理音乐。</p><h2 id="播放控制" tabindex="-1">播放控制 <a class="header-anchor" href="#播放控制" aria-label="Permalink to &quot;播放控制&quot;">​</a></h2><p>Still 支持顺序播放、列表循环、单曲循环和随机播放，也支持播放队列、插播和拖拽调整队列顺序。</p><p>在 Electron 桌面环境中，Still 还支持系统托盘和任务栏媒体控制。</p>',16)])])}const _=a(o,[["render",r]]);export{u as __pageData,_ as default};
